SeasonSwitch s = new SeasonSwitch();
s.cool();
s.ac.off();
s.room.temp = 69;
String out = TestSupport.captureOut(s::timerOff);
assertEquals(List.of("Cooling started. RmTemp=69"), TestSupport.lines(out));
assertTrue(s.ac.isOn);

